#include <complex>
#include <span>
#include <list>
#include <tuple>

using dcomp = std::complex<double>;

void apply_sparse_matrix(std::span<const dcomp> psi, std::span<dcomp> dpsidt, const std::list<std::tuple<size_t, size_t, dcomp>>& elements) {
    // Initialize output to zero first
    for (auto& val : dpsidt) {
        val = dcomp(0.0, 0.0);
