        if (col >= psi.size()) throw std::out_of_range("Column index out of range in apply_sparse_matrix");
        #endif

        dpsidt[row] += value * psi[col];
    }
}

void apply_sparse_matrix(std::span<const dcomp> psi, std::span<dcomp> dpsidt, const std::list<std::tuple<size_t, size_t, dcomp>>& elements) {
    for (auto& val : dpsidt) val = dcomp(0.0, 0.0);
